head.script:
scwin.input1_onkeyup = function(e) {
    //        debugger;
    alert('onkeyup 이벤트!')
};
scwin.selectbox1_onviewchange = function(e) {
    console.log("onviewchange");
};
scwin.selectbox1_onselected = function(info) {
    //        debugger;
    console.log("onselected", info);
    localStorage.setItem("log", "onselected");
    //WebSquare.wUnit.getDomById('input1').focus();
};
scwin.trigger1_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#selectbox1_itemTable_2', 'key-combo', {
        combo: 'up-arrow'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#selectbox1_itemTable_2', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onselected'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
